import 'package:cloud_firestore/cloud_firestore.dart';
class SocialFundRecord { final String id,type,description; final double amount; final DateTime date; const SocialFundRecord({required this.id,required this.type,required this.amount,this.description='',required this.date}); factory SocialFundRecord.fromMap(String id, Map<String,dynamic> m)=>SocialFundRecord(id:id,type:m['type']??'contribution',amount:(m['amount']??0).toDouble(),description:m['description']??'',date:(m['date'] as Timestamp?)?.toDate()??DateTime.now()); Map<String,dynamic> toMap()=>{'type':type,'amount':amount,'description':description,'date':Timestamp.fromDate(date)}; @override String toString()=> '$type • TZS $amount • $description'; }
